'use strict';
const STEPS = ['credentials', 'mfa', 'session'];
function nextStep(current) {
  const idx = STEPS.indexOf(current);
  return idx >= 0 && idx < STEPS.length - 1 ? STEPS[idx + 1] : null;
}
function isComplete(current) {
  return current === STEPS[STEPS.length - 1];
}
module.exports = { nextStep, isComplete, STEPS };

'use strict';
function orderTotal(items, taxRate) {
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  return subtotal + subtotal * (taxRate || 0);
}
function canCheckout(cart) {
  return Array.isArray(cart.items) && cart.items.length > 0 && Boolean(cart.payment);
}
module.exports = { orderTotal, canCheckout };

'use strict';
function progressPercent(completed, total) {
  return total > 0 ? Math.round((completed / total) * 100) : 0;
}
function currentTier(percent) {
  if (percent >= 100) return 'advanced';
  if (percent >= 50) return 'intermediate';
  return 'basic';
}
module.exports = { progressPercent, currentTier };

'use strict';
function matchRoute(routes, method, pathName) {
  return routes.find((r) => r.method === method && r.path === pathName) || null;
}
function routeKey(method, pathName) {
  return method.toUpperCase() + ' ' + pathName;
}
module.exports = { matchRoute, routeKey };

'use strict';
function mergeContracts(contracts) {
  const merged = {};
  for (const c of contracts) {
    for (const key of Object.keys(c || {})) merged[key] = c[key];
  }
  return merged;
}
function missingDependencies(provided, required) {
  return required.filter((dep) => !provided.includes(dep));
}
module.exports = { mergeContracts, missingDependencies };
